<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, Check, CheckCheck, CheckCircle2, ChevronRight, CircleHelp, Database, FileCheck2, Files, GitCompareArrows, LayoutDashboard, ListChecks, LogOut, Play, Plus, RefreshCw, Scale, Search, ShieldCheck, Upload, Wallet, XCircle, X } from '@lucide/vue'
import Modal from './components/Modal.vue'
import { api, download, money, label, time, plusDay } from './api'
import type { Row } from './api'

const session=ref<Row>({authenticated:false}),ready=ref(false),busy=ref(false),loading=ref(false)
const login=reactive({username:'admin',password:'demo123456'}),loginError=ref('')
const view=ref('overview'),search=ref(''),modal=ref(''),toast=ref(''),toastError=ref(false)
const dashboard=ref<Row>({overview:{},trend:[],latest:[],distribution:[],today:''})
const channels=ref<Row[]>([]),projects=ref<Row[]>([]),runs=ref<Row[]>([]),differences=ref<Row[]>([]),batches=ref<Row[]>([]),records=ref<Row[]>([]),vouchers=ref<Row[]>([]),audits=ref<Row[]>([])
const dataTab=ref('batches'),differenceFilter=ref(''),sourceFilter=ref(''),recordDate=ref('')
const chosenFile=ref<File>(),runDetail=ref<Row>(),differenceDetail=ref<Row>(),selectedDifference=ref<Row>({})
const projectForm=reactive<Row>({}),channelForm=reactive<Row>({}),runForm=reactive<Row>({}),importForm=reactive<Row>({}),resolutionForm=reactive<Row>({}),reviewNote=ref('')
let toastTimer:ReturnType<typeof setTimeout>
const nav=[{id:'overview',title:'对账总览',icon:LayoutDashboard},{id:'projects',title:'对账项目',icon:GitCompareArrows},{id:'data',title:'数据中心',icon:Database},{id:'runs',title:'对账任务',icon:ListChecks},{id:'differences',title:'差错处理',icon:FileCheck2},{id:'accounts',title:'资金账户',icon:Wallet},{id:'vouchers',title:'账务凭证',icon:Files},{id:'audit',title:'操作审计',icon:ShieldCheck}]
const currentTitle=computed(()=>nav.find(n=>n.id===view.value)?.title??'对账中心')
const reviewer=computed(()=>session.value.reviewer===true)
const today=computed(()=>dashboard.value.today||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong'}).format(new Date()))
const yesterday=computed(()=>plusDay(today.value,-1))
const rate=computed(()=>{const total=dashboard.value.trend.reduce((s:number,r:Row)=>s+Number(r.total_count),0);const matched=dashboard.value.trend.reduce((s:number,r:Row)=>s+Number(r.matched_count),0);return total?(matched/total*100).toFixed(2):'0.00'})
const maxChart=computed(()=>Math.max(1,...dashboard.value.trend.map((r:Row)=>Number(r.total_count))))
const selectedProject=computed(()=>projects.value.find(p=>String(p.id)===String(runForm.projectId)))
const pendingRequest=computed(()=>differenceDetail.value?.requests?.find((r:Row)=>r.status==='PENDING'))
const remaining=computed(()=>{const d=selectedDifference.value;let delta=BigInt(String(d.delta??0));if(delta<0n)delta=-delta;return(delta-BigInt(String(d.resolved_amount??0))).toString()})
const filteredDifferences=computed(()=>filtered(differences.value).filter(d=>!differenceFilter.value||d.status===differenceFilter.value))
const unresolved=computed(()=>differences.value.filter(d=>!['RESOLVED','SUPERSEDED'].includes(d.status)))
const matchedTotal=computed(()=>dashboard.value.distribution.filter((d:Row)=>d.result==='MATCHED').reduce((s:number,r:Row)=>s+Number(r.count),0))
const comparisonTotal=computed(()=>dashboard.value.distribution.reduce((s:number,r:Row)=>s+Number(r.count),0))
function filtered(rows:Row[]) {const needle=search.value.trim().toLowerCase();return needle?rows.filter(row=>JSON.stringify(row).toLowerCase().includes(needle)):rows}
function notify(message:string,error=false){toast.value=message;toastError.value=error;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',6000)}
function navigate(id:string){view.value=id;search.value='';window.scrollTo({top:0})}
watch(view,()=>{window.location.hash=view.value})
function sessionExpired(){session.value={authenticated:false}}
async function load(){
  loading.value=true
  try {
    const result=await Promise.all([api('/dashboard'),api<Row[]>('/channels'),api<Row[]>('/projects'),api<Row[]>('/runs'),api<Row[]>('/differences'),api<Row[]>('/imports'),api<Row[]>('/vouchers'),api<Row[]>('/audit')])
    ;[dashboard.value,channels.value,projects.value,runs.value,differences.value,batches.value,vouchers.value,audits.value]=result
  } finally {loading.value=false}
}
async function refresh(){try{await load();if(view.value==='data'&&dataTab.value==='records')await loadRecords();notify('数据已更新')}catch(error){notify((error as Error).message,true)}}
async function signIn(){busy.value=true;loginError.value='';try{await api('/login',{method:'POST',body:JSON.stringify(login)});session.value=await api('/session');await load()}catch(error){loginError.value=(error as Error).message}finally{busy.value=false}}
async function logout(){try{await api('/logout',{method:'POST'});session.value=await api('/session');modal.value='';login.password=''}catch(error){notify((error as Error).message,true)}}
async function perform(action:()=>Promise<unknown>,message:string|((result:any)=>string)){busy.value=true;try{const result=await action();modal.value='';await load();notify(typeof message==='function'?message(result):message)}catch(error){notify((error as Error).message,true)}finally{busy.value=false}}
async function loadRecords(){const query=new URLSearchParams();if(sourceFilter.value)query.set('source',sourceFilter.value);if(recordDate.value)query.set('date',recordDate.value);try{records.value=await api(`/source-records?${query}`)}catch(error){notify((error as Error).message,true)}}
function openProject(project?:Row){Object.assign(projectForm,{id:null,name:'',kind:'TRANSACTION',channelId:channels.value[0]?.id,leftSource:'PLATFORM',rightSource:'CLEARING',matchMode:'ONE_TO_ONE',tolerance:'0.00',settlementDays:0,startDate:yesterday.value,enabled:true,autoRun:false,scheduleTime:'09:00',locked:false});if(project)Object.assign(projectForm,{id:project.id,name:project.name,kind:project.kind,channelId:project.channel_id,leftSource:project.left_source,rightSource:project.right_source,matchMode:project.match_mode,tolerance:money(project.tolerance).replaceAll(',',''),settlementDays:project.settlement_days,startDate:project.start_date,enabled:project.enabled,autoRun:project.auto_run,scheduleTime:project.schedule_time,locked:!!project.last_date});modal.value='project'}
function projectKindChange(){if(projectForm.kind==='BALANCE'){projectForm.leftSource='PLATFORM';projectForm.rightSource='SETTLEMENT';projectForm.matchMode='GROUPED';projectForm.autoRun=false}else if(projectForm.kind==='FUND'){projectForm.leftSource='CLEARING';projectForm.rightSource='SETTLEMENT';projectForm.matchMode='GROUPED'}else{projectForm.leftSource='PLATFORM';projectForm.rightSource='CLEARING';projectForm.matchMode='ONE_TO_ONE'}projectForm.settlementDays=0}
function openChannel(){Object.assign(channelForm,{name:'',code:'',merchantNo:'',openingDate:yesterday.value,openingBalance:'0.00'});modal.value='channel'}
function openRun(project?:Row){const p=project??projects.value.find(p=>p.enabled);if(!p){notify('请先创建并启用对账项目',true);return}Object.assign(runForm,{projectId:p.id,businessDate:p.requires_rerun?p.last_date:(p.last_date?plusDay(p.last_date):p.start_date),rerun:!!p.requires_rerun,leftAdjustment:'0.00',rightAdjustment:'0.00'});modal.value='run'}
function runProjectChange(){const p=selectedProject.value;if(p){runForm.businessDate=runForm.rerun?p.last_date:(p.last_date?plusDay(p.last_date):p.start_date)}}
function openImport(){Object.assign(importForm,{channelId:channels.value[0]?.id,source:'PLATFORM',businessDate:yesterday.value});chosenFile.value=undefined;modal.value='import'}
function importFile(event:Event){chosenFile.value=(event.target as HTMLInputElement).files?.[0]}
async function submitImport(){if(!chosenFile.value){notify('请选择 CSV 文件',true);return}const data=new FormData();data.set('channelId',importForm.channelId);data.set('source',importForm.source);data.set('businessDate',importForm.businessDate);data.set('file',chosenFile.value);await perform(()=>api('/imports',{method:'POST',body:data}),r=>r.duplicate?'相同账单已导入，已跳过本次重复请求':`导入完成：新增 ${r.inserted} 行，跳过 ${r.skipped} 行${Number(r.requiresRerun)?'；相关任务已标记为需重对':''}`)}
async function showRun(row:Row){try{runDetail.value=await api(`/runs/${row.id}`);modal.value='run-detail'}catch(error){notify((error as Error).message,true)}}
async function showDifference(row:Row){try{selectedDifference.value=row;differenceDetail.value=await api(`/differences/${row.id}`);Object.assign(resolutionForm,{amount:money(remaining.value).replaceAll(',',''),method:'MANUAL_CONFIRM',note:'',evidence:''});reviewNote.value='';modal.value='difference'}catch(error){notify((error as Error).message,true)}}
async function downloadFile(path:string,name:string){try{await download(path,name)}catch(error){notify((error as Error).message,true)}}
async function runTask(){await perform(()=>api('/runs',{method:'POST',body:JSON.stringify(runForm)}),r=>r.duplicate?'该日期已完成，已返回原执行结果':'对账任务执行完成')}
onMounted(async()=>{window.addEventListener('session-expired',sessionExpired);if(nav.some(n=>n.id===window.location.hash.slice(1)))view.value=window.location.hash.slice(1);try{session.value=await api('/session');if(session.value.authenticated)await load()}catch(error){loginError.value=(error as Error).message}finally{ready.value=true}})
onBeforeUnmount(()=>{window.removeEventListener('session-expired',sessionExpired);clearTimeout(toastTimer)})
</script>

<template>
  <div v-if="!ready" class="initial-loading"><Scale :size="38"/><span>衡账 · 正在连接工作台</span></div>
  <main v-else-if="!session.authenticated" class="login-screen">
    <section class="login-story"><div class="brand"><span class="brand-mark"><Scale :size="25"/></span><span>衡账<span class="brand-en">HENGZHANG</span></span></div><div class="login-story-main"><span class="eyebrow">CLARITY IN EVERY TRANSACTION</span><h1>让每一笔往来，<br/>都有清晰的答案。</h1><p>从交易明细到资金余额，连接数据、发现差异，<br/>让对账工作有序发生。</p><div class="login-orbit"><div class="orbit-line"></div><span class="orbit-chip"><Database :size="18"/> 业务数据</span><span class="orbit-center"><Scale :size="42"/></span><span class="orbit-chip"><CheckCheck :size="18"/> 账实相符</span></div><div class="login-features"><span><CheckCircle2 :size="16"/> 三种对账模型</span><span><ShieldCheck :size="16"/> 提交与复核分离</span><span><Files :size="16"/> 完整审计记录</span></div></div><small>HENGZHANG RECONCILIATION CENTER · 2026</small></section>
    <section class="login-panel"><form class="login-form" @submit.prevent="signIn"><span class="eyebrow">WELCOME TO YOUR WORKSPACE</span><h2>登录对账中心</h2><p class="muted">在一个工作台，掌握每一笔账的状态。</p><label>操作账号<input v-model="login.username" name="username" autocomplete="username" required placeholder="请输入账号"/></label><label>登录密码<input v-model="login.password" name="password" autocomplete="current-password" type="password" required placeholder="请输入密码"/></label><p v-if="loginError" role="alert" class="form-error">{{loginError}}</p><button class="button primary login-submit" :disabled="busy">{{busy?'正在登录…':'进入工作台'}}<ArrowRight :size="17"/></button><div class="demo-credentials"><ShieldCheck :size="18"/><div><b>本地演示账号</b><p>操作员 admin / demo123456<br/>复核员 reviewer / demo123456</p><small>密码可通过启动环境变量修改</small></div></div></form></section>
  </main>
  <div v-else class="app-shell">
    <aside class="sidebar"><a href="#overview" class="brand" @click.prevent="navigate('overview')"><span class="brand-mark"><Scale :size="23"/></span><span>衡账<span class="brand-en">HENGZHANG</span></span></a><div class="workspace-switch"><span class="workspace-avatar">H</span><span><strong>对账管理工作台</strong><small>本地运行 · CNY</small></span><ShieldCheck :size="16"/></div><span class="nav-caption">WORKSPACE / 工作空间</span><nav><button v-for="item in nav" :key="item.id" :class="['nav-item',{active:view===item.id}]" @click="navigate(item.id)"><component :is="item.icon" :size="19"/><span>{{item.title}}</span><span v-if="item.id==='differences'&&Number(dashboard.overview.pending_count)" class="nav-count">{{dashboard.overview.pending_count}}</span><ChevronRight v-else-if="view===item.id" :size="14" class="nav-chevron"/></button></nav><div class="sidebar-bottom"><div class="system-status"><span class="status-dot"></span>本地数据库已连接<span class="version">v1.0</span></div><button class="sidebar-help" @click="modal='help'"><CircleHelp :size="17"/><span>使用指南</span><ArrowUpRight :size="14"/></button><div class="sidebar-user"><span class="avatar">{{reviewer?'R':'H'}}</span><span><b>{{reviewer?'财务复核员':'对账管理员'}}</b><small>{{session.username}} · {{reviewer?'复核权限':'操作权限'}}</small></span><button title="退出登录" aria-label="退出登录" @click="logout"><LogOut :size="17"/></button></div></div></aside>
    <div class="main-shell"><header class="topbar"><div class="breadcrumb">工作空间<ChevronRight :size="14"/><span>{{currentTitle}}</span></div><div class="topbar-right"><span class="top-date">{{today.replaceAll('-',' / ')}}</span><button class="notification" aria-label="查看待处理差异" @click="navigate('differences')"><Bell :size="18"/><i v-if="unresolved.length"></i></button><span class="top-divider"></span><span class="small-avatar">{{reviewer?'R':'H'}}</span></div></header>
      <main class="main-content"><div class="page-heading"><div><span class="eyebrow">{{view==='overview'?'YOUR FINANCIAL OPERATIONS, IN SYNC.':'HENGZHANG / RECONCILIATION WORKSPACE'}}</span><h1>{{view==='overview'?'对账总览':currentTitle}}<span v-if="view==='overview'" class="live-badge"><span class="status-dot"></span> 实时工作台</span></h1><p class="muted">{{({overview:'让数据对齐，让资金有数。今天的对账进展，尽在掌握。',projects:'将核对方式沉淀为规则，让每一次执行有据可循。',data:'统一归集平台、清算与结算数据，保留每一份原始账单。',runs:'按日期连续执行，完整保留每一次核对的结果。',differences:'发现只是开始，让每一笔差异都有处理的闭环。',accounts:'从准确的期初余额开始，建立清晰的资金核对边界。',vouchers:'差异挂账、重对冲销与核销凭证，逐笔留存。',audit:'谁在什么时候做了什么，始终清晰可查。'} as Record<string,string>)[view]}}</p></div><div class="heading-actions"><button class="button secondary icon-only" aria-label="刷新数据" title="刷新数据" :disabled="loading" @click="refresh"><RefreshCw :size="17" :class="{spin:loading}"/></button><button v-if="view==='overview'&&!reviewer" class="button secondary" @click="openImport"><Upload :size="16"/>导入账单</button><button v-if="['overview','runs'].includes(view)&&!reviewer" class="button primary" @click="openRun()"><Play :size="15"/>发起对账</button><button v-if="view==='projects'&&!reviewer" class="button primary" @click="openProject()"><Plus :size="17"/>新建对账项目</button><button v-if="view==='data'&&!reviewer" class="button primary" @click="openImport"><Upload :size="17"/>导入账单</button><button v-if="view==='accounts'&&!reviewer" class="button primary" @click="openChannel"><Plus :size="17"/>新增资金账户</button><button v-if="view==='differences'" class="button secondary" @click="downloadFile('/export/differences.csv','对账差异.csv')"><ArrowDownToLine :size="16"/>导出差异</button></div></div>

      <template v-if="view==='overview'"><button v-if="Number(dashboard.overview.stale_count)" class="stale-notice" @click="navigate('projects')"><RefreshCw :size="16"/>{{dashboard.overview.stale_count}} 个任务的账单已更新，请重新对账；旧结果已从统计与差错处理排除。<ArrowRight :size="14"/></button>
        <section class="overview-banner"><div><span class="banner-pill"><ShieldCheck :size="13"/> 每一笔，都有据可核</span><h2>账目清晰，业务从容。</h2><p>从交易到资金，从发现到处理，构建完整的对账闭环。</p></div><div class="banner-graphic" aria-hidden="true"><span class="graphic-orbit"></span><div class="graphic-card back"><span></span><span></span><span></span></div><div class="graphic-card front"><div class="graphic-logo"><Scale :size="20"/></div><span></span><span></span><div class="graphic-check"><Check :size="19"/></div></div><span class="graphic-spark s1">+</span><span class="graphic-spark s2">+</span></div></section>
        <section class="kpi-grid"><article class="kpi-card"><div class="kpi-label">已归集数据<span class="kpi-icon green"><Database :size="17"/></span></div><div class="kpi-number">{{Number(dashboard.overview.record_count||0).toLocaleString()}}<small>笔</small></div><div class="kpi-foot"><span class="green-text"><CheckCircle2 :size="12"/> 已完成入库</span><span>三类原始数据</span></div></article><article class="kpi-card"><div class="kpi-label">近 7 日对平率<span class="kpi-icon blue"><CheckCheck :size="18"/></span></div><div class="kpi-number">{{rate}}<small>%</small></div><div class="kpi-foot"><span class="mini-line"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span><span>按核对标识统计</span></div></article><article class="kpi-card"><div class="kpi-label">待处理差异<span class="kpi-icon orange"><GitCompareArrows :size="17"/></span></div><div class="kpi-number">{{dashboard.overview.pending_count||0}}<small>笔</small></div><button class="kpi-link" @click="navigate('differences')">{{Number(dashboard.overview.pending_count)?'进入差错处理':'查看处理记录'}}<ArrowRight :size="13"/></button></article><article class="kpi-card"><div class="kpi-label">待核销差异金额<span class="kpi-icon purple"><Wallet :size="17"/></span></div><div class="kpi-number money-number"><small>¥</small>{{money(dashboard.overview.pending_amount)}}</div><div class="kpi-foot"><span class="muted-dot"></span><span>各模型未核销差额绝对值合计</span></div></article></section>
        <section class="chart-grid"><article class="panel trend-panel"><div class="panel-heading"><div><h2>对账运行趋势</h2><p>近 7 日核对标识数量 · 全部模型</p></div><div class="legend"><span><i class="legend-dot matched"></i>对平</span><span><i class="legend-dot difference"></i>差异</span></div></div><div v-if="dashboard.trend.length" class="bar-chart"><div class="chart-labels"><span>{{maxChart}}</span><span>{{Math.round(maxChart/2)}}</span><span>0</span></div><div class="chart-plot"><div class="chart-gridlines"><i></i><i></i><i></i></div><div class="chart-bars"><div v-for="day in dashboard.trend" :key="day.business_date" class="chart-day"><div class="bar-stack" :style="{height:`${Math.max(2,Number(day.total_count)/maxChart*100)}%`}" :title="`${day.business_date}：对平 ${day.matched_count}，差异 ${day.difference_count}`"><div class="bar-difference" :style="{height:`${Number(day.difference_count)/Math.max(1,Number(day.total_count))*100}%`}"></div><div class="bar-matched" :style="{flex:1}"></div></div><span>{{day.business_date.slice(5).replace('-','/')}}</span></div></div></div></div><div v-else class="empty-state">完成一次对账后，趋势会显示在这里。</div><footer class="panel-foot"><span><span class="status-dot"></span>统计来自实际执行结果</span><span>仅统计最新且未过期的结果</span></footer></article><article class="panel distribution-panel"><div class="panel-heading"><div><h2>核对结果分布</h2><p>全部有效任务的累计结果</p></div><GitCompareArrows :size="18" class="muted"/></div><div class="donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="img" :aria-label="`共 ${comparisonTotal} 个核对标识，${matchedTotal} 个对平`"><circle cx="80" cy="80" r="61" fill="none" stroke="#f1d7a8" stroke-width="13"/><circle cx="80" cy="80" r="61" fill="none" stroke="#247965" stroke-width="13" :stroke-dasharray="`${comparisonTotal?matchedTotal/comparisonTotal*383.27:0} 383.27`" transform="rotate(-90 80 80)" stroke-linecap="round"/></svg><div class="donut-text"><strong>{{comparisonTotal.toLocaleString()}}</strong><span>核对标识</span></div></div><div class="distribution-summary"><span><i class="legend-dot matched"></i>已对平<b>{{matchedTotal}}</b></span><span><i class="legend-dot difference"></i>有差异<b>{{comparisonTotal-matchedTotal}}</b></span></div></article></section>
        <section class="bottom-grid"><article class="panel recent-panel"><div class="panel-heading"><div><h2>最近对账任务<span class="count-badge">{{dashboard.latest.length}}</span></h2><p>交易、资金和余额，进展一目了然</p></div><button class="text-button muted" @click="navigate('runs')">查看全部<ArrowRight :size="14"/></button></div><div class="table-wrap"><table><thead><tr><th>对账项目 / 日期</th><th>对账类型</th><th>对平 / 总数</th><th>执行结果</th><th></th></tr></thead><tbody><tr v-for="run in dashboard.latest" :key="run.id"><td><b class="cell-main">{{run.project_name}}</b><span class="cell-sub">{{run.business_date}}<span class="sub-separator">·</span>#{{run.id}}</span></td><td><span class="type-tag">{{label(run.kind)}}</span></td><td class="tabular">{{run.matched_count}}<span class="muted"> / {{run.total_count}}</span></td><td><span :class="['badge',run.stale||Number(run.difference_count)?'warning':'success']"><i></i>{{run.stale?'账单已更新 · 需重对':Number(run.difference_count)?`${run.difference_count} 笔差异`:'全部对平'}}</span></td><td><button class="row-arrow" :aria-label="`查看任务 ${run.id}`" @click="showRun(run)"><ArrowUpRight :size="17"/></button></td></tr><tr v-if="!dashboard.latest.length"><td colspan="5" class="empty-cell">尚无对账任务，导入账单后即可发起。</td></tr></tbody></table></div></article><article class="panel workflow-panel"><div class="panel-heading"><div><h2>对账工作流</h2><p>从原始账单到差错闭环</p></div><span class="tiny-tag">5 STEPS</span></div><ol class="workflow"><li v-for="(step,i) in [{title:'数据归集',desc:`${batches.length} 份账单已入库`,target:'data',icon:Database},{title:'交易核对',desc:'平台支付账 ↔ 渠道清算账',target:'projects',icon:GitCompareArrows},{title:'资金核对',desc:'应收应付 ↔ 实收实付',target:'runs',icon:Wallet},{title:'余额调节',desc:'期初余额 + 资金变动 + 在途',target:'runs',icon:Scale},{title:'差错处理',desc:unresolved.length?`${unresolved.length} 笔差异等待跟进`:'当前暂无待处理差异',target:'differences',icon:FileCheck2}]" :key="step.title"><span :class="['workflow-number',{last:i===4}]"><component :is="step.icon" :size="16"/></span><button @click="navigate(step.target)"><b>{{step.title}}</b><small>{{step.desc}}</small></button><ChevronRight :size="14"/></li></ol></article></section>
      </template>

      <template v-else>
        <div v-if="view!=='accounts'" class="table-toolbar"><div class="search-field"><Search :size="16"/><input v-model="search" :placeholder="view==='differences'?'搜索项目、核对标识或差异类型…':'搜索当前列表…'" aria-label="搜索当前列表"/><button v-if="search" aria-label="清空搜索" @click="search=''"><X :size="14"/></button></div><div v-if="view==='data'" class="tabs"><button :class="{active:dataTab==='batches'}" @click="dataTab='batches'">账单批次</button><button :class="{active:dataTab==='records'}" @click="dataTab='records';loadRecords()">原始明细</button></div><select v-if="view==='differences'" v-model="differenceFilter" aria-label="差异处理状态"><option value="">全部处理状态</option><option v-for="s in ['OPEN','INVESTIGATING','PENDING_REVIEW','RESOLVED']" :key="s" :value="s">{{label(s)}}</option></select><div v-if="view==='data'&&dataTab==='records'" class="record-filters"><select v-model="sourceFilter" aria-label="数据源筛选" @change="loadRecords"><option value="">全部数据源</option><option v-for="s in ['PLATFORM','CLEARING','SETTLEMENT']" :key="s" :value="s">{{label(s)}}</option></select><input v-model="recordDate" type="date" aria-label="账单日期筛选" @change="loadRecords"/></div><span class="table-hint">{{view==='data'&&dataTab==='records'?'按条件展示最近 500 条':'最多展示最近 500 条'}}</span></div>
        <section v-if="view==='projects'" class="panel"><div class="table-wrap"><table><thead><tr><th>对账项目</th><th>模型 / 核对方式</th><th>核对数据源</th><th>最后对账日</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in filtered(projects)" :key="p.id"><td><b class="cell-main">{{p.name}}</b><span class="cell-sub">{{p.channel_name}} · #{{p.id}}</span></td><td>{{label(p.kind)}}<span class="cell-sub">{{p.kind==='FUND'?`按费用项 · T+${p.settlement_days}`:p.kind==='BALANCE'?'累计余额 + 在途调整':label(p.match_mode)}}</span></td><td><span class="source-flow">{{label(p.left_source)}}<ArrowRight :size="13"/>{{label(p.right_source)}}</span><span class="cell-sub">容差 ¥{{money(p.tolerance)}}</span></td><td class="tabular">{{p.last_date||'尚未执行'}}<span class="cell-sub">{{p.requires_rerun?'账单已更新 · 需重对':p.auto_run?`自动 · ${p.schedule_time}`:'手动执行'}}</span></td><td><span :class="['badge',p.enabled?'success':'neutral']"><i></i>{{p.enabled?'已启用':'已停用'}}</span></td><td><div v-if="!reviewer" class="row-actions"><button class="text-button" @click="openProject(p)">配置</button><button class="text-button" :disabled="!p.enabled" @click="openRun(p)">执行<Play :size="12"/></button></div><span v-else class="muted">只读</span></td></tr><tr v-if="!filtered(projects).length"><td colspan="6" class="empty-cell">暂无符合条件的对账项目</td></tr></tbody></table></div></section>
        <section v-if="view==='data'" class="panel"><div class="table-wrap"><table v-if="dataTab==='batches'"><thead><tr><th>账单文件</th><th>资金账户</th><th>数据源</th><th>账单日期</th><th>新增 / 跳过</th><th>导入时间</th><th>操作人</th></tr></thead><tbody><tr v-for="b in filtered(batches)" :key="b.id"><td><span class="file-cell"><span class="file-icon"><Files :size="17"/></span><span><b class="cell-main">{{b.filename}}</b><span class="cell-sub">批次 #{{b.id}}</span></span></span></td><td>{{b.channel_name}}</td><td><span class="type-tag">{{label(b.source)}}</span></td><td class="tabular">{{b.business_date}}</td><td>{{b.inserted_count}}<span class="muted"> / {{b.skipped_count}}</span></td><td class="tabular">{{time(b.created_at)}}</td><td>{{b.actor}}</td></tr><tr v-if="!filtered(batches).length"><td colspan="7" class="empty-cell">暂无账单，请导入 CSV 或通过接口接收数据。</td></tr></tbody></table><table v-else><thead><tr><th>订单号 / 流水号</th><th>数据源</th><th>业务类型</th><th class="align-right">金额（元）</th><th>交易状态</th><th>交易日期</th></tr></thead><tbody><tr v-for="r in filtered(records)" :key="r.id"><td><b class="cell-main mono">{{r.order_no}}</b><span class="cell-sub mono">{{r.external_id}}</span></td><td>{{label(r.source)}}</td><td>{{label(r.business_type)}}</td><td class="align-right tabular">{{money(r.amount)}}</td><td><span :class="['badge',r.trade_status==='SUCCESS'?'success':'warning']">{{label(r.trade_status)}}</span></td><td class="tabular">{{r.trade_date}}</td></tr><tr v-if="!filtered(records).length"><td colspan="6" class="empty-cell">暂无符合条件的原始数据</td></tr></tbody></table></div></section>
        <section v-if="view==='runs'" class="panel"><div class="table-wrap"><table><thead><tr><th>任务 / 项目</th><th>对账日期</th><th>模型</th><th>核对标识</th><th>对平 / 差异</th><th>版本</th><th>执行时间</th><th></th></tr></thead><tbody><tr v-for="r in filtered(runs)" :key="r.id" :class="{superseded:!r.active}"><td><b class="cell-main">{{r.project_name}}</b><span class="cell-sub">#{{r.id}} · {{r.actor}}</span></td><td class="tabular">{{r.business_date}}</td><td><span class="type-tag">{{label(r.kind)}}</span></td><td>{{r.total_count}}</td><td><span class="green-text">{{r.matched_count}}</span> / <span :class="{'amber-text':Number(r.difference_count)>0}">{{r.difference_count}}</span></td><td><span :class="['badge',r.stale&&r.active?'warning':r.active?'success':'neutral']">v{{r.attempt}} · {{!r.active?'已重对':r.stale?'需重对':'有效'}}</span></td><td>{{time(r.created_at)}}<span class="cell-sub">计算 {{r.duration_ms}} ms</span></td><td><button class="text-button" @click="showRun(r)">查看明细<ArrowUpRight :size="14"/></button></td></tr><tr v-if="!filtered(runs).length"><td colspan="8" class="empty-cell">暂无执行记录</td></tr></tbody></table></div></section>
        <section v-if="view==='differences'" class="panel"><div class="inline-notice"><ShieldCheck :size="16"/>核销采用提交与复核分离流程；支持分次核销，每次通过复核后登记本地账务凭证。</div><div class="table-wrap"><table><thead><tr><th>核对标识 / 项目</th><th>差异类型</th><th class="align-right">A 方 / B 方（元）</th><th class="align-right">差额 / 已核销（元）</th><th>处理状态</th><th>对账日期</th><th></th></tr></thead><tbody><tr v-for="d in filteredDifferences" :key="d.id"><td><b class="cell-main mono">{{d.match_key}}</b><span class="cell-sub">{{d.project_name}} · #{{d.id}}</span></td><td><span class="badge warning">{{label(d.result)}}</span></td><td class="align-right tabular">{{money(d.left_amount)}}<span class="cell-sub">{{money(d.right_amount)}}</span></td><td class="align-right tabular"><b class="amber-text">{{money(d.delta)}}</b><span class="cell-sub">已核销 {{money(d.resolved_amount)}}</span></td><td><span :class="['badge',d.status==='RESOLVED'?'success':d.status==='PENDING_REVIEW'?'purple':'neutral']"><i></i>{{label(d.status)}}</span></td><td class="tabular">{{d.business_date}}</td><td><button class="text-button" @click="showDifference(d)">{{reviewer&&d.status==='PENDING_REVIEW'?'复核':'查看处理'}}<ArrowUpRight :size="14"/></button></td></tr><tr v-if="!filteredDifferences.length"><td colspan="7" class="empty-cell">暂无符合条件的差异</td></tr></tbody></table></div></section>
        <section v-if="view==='accounts'" class="account-grid"><article v-for="c in channels" :key="c.id" class="panel account-card"><div class="account-head"><span class="account-icon"><Wallet :size="24"/></span><span class="type-tag">CNY 人民币</span></div><h2>{{c.name}}</h2><p class="muted mono">{{c.merchant_no}}</p><div class="account-balance"><span>启用时点期初余额</span><strong><small>¥</small>{{money(c.opening_balance)}}</strong></div><div class="account-details"><span>账户编码<b>{{c.code}}</b></span><span>启用日期<b>{{c.opening_date}}</b></span><span>关联对账项目<b>{{c.project_count}} 个</b></span></div><footer><ShieldCheck :size="14"/>期初余额在创建后保留，变更请建立新账户</footer></article><div v-if="!channels.length" class="panel empty-state">尚未添加资金账户</div></section>
        <section v-if="view==='vouchers'" class="panel"><div class="inline-notice"><Scale :size="16"/>每份凭证同时登记等额借方与贷方；按项目设置挂账账户，避免将不同核对模型混为总账。</div><div class="table-wrap"><table><thead><tr><th>凭证 / 类型</th><th>借方账户</th><th>贷方账户</th><th class="align-right">借贷各记（元）</th><th>摘要</th><th>登记时间 / 操作人</th></tr></thead><tbody><tr v-for="v in filtered(vouchers)" :key="v.id"><td><b class="cell-main mono">HZ-V{{String(v.id).padStart(6,'0')}}</b><span class="cell-sub">{{label(v.reference_type)}} · #{{v.reference_id}}</span></td><td>{{label(v.debit_account)}}</td><td>{{label(v.credit_account)}}</td><td class="align-right tabular">{{money(v.amount)}}</td><td>{{v.note}}<span v-if="v.reversal_of" class="cell-sub">冲销原凭证 #{{v.reversal_of}}</span></td><td>{{time(v.created_at)}}<span class="cell-sub">{{v.actor}}</span></td></tr><tr v-if="!filtered(vouchers).length"><td colspan="6" class="empty-cell">有金额的差异会自动登记挂账凭证。</td></tr></tbody></table></div></section>
        <section v-if="view==='audit'" class="panel"><div class="table-wrap"><table><thead><tr><th>审计事件</th><th>操作人</th><th>业务对象</th><th>操作详情</th><th>发生时间</th></tr></thead><tbody><tr v-for="a in filtered(audits)" :key="a.id"><td><span class="audit-action"><ShieldCheck :size="15"/>{{label(a.action)}}</span></td><td><span class="actor-tag">{{a.actor}}</span></td><td class="mono">{{a.target}}</td><td class="audit-detail">{{a.detail}}</td><td class="tabular nowrap">{{time(a.created_at)}}</td></tr><tr v-if="!filtered(audits).length"><td colspan="5" class="empty-cell">暂无符合条件的审计事件</td></tr></tbody></table></div></section>
      </template>
      <footer class="page-footer"><span><Scale :size="13"/>衡账 · 让每一笔，都有据可核</span><span>交易核对 / 资金核对 / 余额调节<span class="footer-divider">|</span>CNY</span></footer>
      </main>
    </div>

    <Modal v-if="modal==='project'" :title="projectForm.id?'配置对账项目':'新建对账项目'" @close="modal=''">
      <form class="modal-form" @submit.prevent="perform(()=>api(projectForm.id?`/projects/${projectForm.id}`:'/projects',{method:projectForm.id?'PUT':'POST',body:JSON.stringify(projectForm)}),'对账项目已保存')"><label>项目名称<input v-model="projectForm.name" required maxlength="100" placeholder="例如：会员订单 · 微信支付核对"/></label><div class="form-grid"><label>对账模型<select v-model="projectForm.kind" :disabled="projectForm.locked" @change="projectKindChange"><option v-for="k in ['TRANSACTION','FUND','BALANCE']" :key="k" :value="k">{{label(k)}}</option></select></label><label>资金账户<select v-model="projectForm.channelId" required :disabled="projectForm.locked"><option v-for="c in channels" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>A 方数据源<select v-model="projectForm.leftSource" :disabled="projectForm.locked||projectForm.kind==='BALANCE'"><option v-for="s in ['PLATFORM','CLEARING','SETTLEMENT']" :key="s" :value="s">{{label(s)}}</option></select></label><label>B 方数据源<select v-model="projectForm.rightSource" :disabled="projectForm.locked||projectForm.kind==='BALANCE'"><option v-for="s in ['PLATFORM','CLEARING','SETTLEMENT']" :key="s" :value="s">{{label(s)}}</option></select></label><label>核对方式<select v-model="projectForm.matchMode" :disabled="projectForm.locked||projectForm.kind!=='TRANSACTION'"><option value="ONE_TO_ONE">逐笔核对 1:1</option><option value="GROUPED">按订单汇总 1:N / N:N</option></select></label><label>金额容差（元）<input v-model="projectForm.tolerance" required inputmode="decimal" :disabled="projectForm.locked"/></label><label>起始对账日<input v-model="projectForm.startDate" required type="date" :disabled="projectForm.locked"/></label><label v-if="projectForm.kind==='FUND'">划付延迟（自然日）<input v-model.number="projectForm.settlementDays" type="number" min="0" max="30" :disabled="projectForm.locked"/></label><label>计划执行时间<input v-model="projectForm.scheduleTime" required type="time"/></label></div><div class="form-checks"><label class="check-label"><input v-model="projectForm.enabled" type="checkbox"/>启用该项目</label><label class="check-label"><input v-model="projectForm.autoRun" :disabled="projectForm.kind==='BALANCE'" type="checkbox"/>自动执行（T+1）</label></div><p class="form-note">{{projectForm.locked?'该项目已有历史结果，规则已锁定；如需调整规则，请新建项目。':'交易以“订单号 + 业务类型”匹配；资金按费用项汇总 SUCCESS 记录。'}} 自动执行还需启动时设置 SCHEDULING_ENABLED=true，余额在途调整需手动执行。</p><footer class="modal-actions"><button type="button" class="button secondary" @click="modal=''">取消</button><button class="button primary" :disabled="busy||!channels.length">{{busy?'保存中…':'保存项目'}}</button></footer></form>
    </Modal>
    <Modal v-if="modal==='channel'" title="新增资金账户" @close="modal=''"><form class="modal-form" @submit.prevent="perform(()=>api('/channels',{method:'POST',body:JSON.stringify(channelForm)}),'资金账户已创建')"><label>账户名称<input v-model="channelForm.name" required maxlength="100" placeholder="例如：微信支付 · 门店收款账户"/></label><div class="form-grid"><label>账户编码<input v-model="channelForm.code" required pattern="[A-Z0-9_-]{2,40}" placeholder="WECHAT_STORE"/></label><label>商户号 / 账户号<input v-model="channelForm.merchantNo" required maxlength="80"/></label><label>启用日期<input v-model="channelForm.openingDate" required type="date" :max="today"/></label><label>期初余额（元）<input v-model="channelForm.openingBalance" required inputmode="decimal"/></label></div><p class="form-note">期初余额指启用日期当天第一笔交易前的余额。创建后保留原值，请与账户凭证核实。</p><footer class="modal-actions"><button type="button" class="button secondary" @click="modal=''">取消</button><button class="button primary" :disabled="busy">创建账户</button></footer></form></Modal>
    <Modal v-if="modal==='import'" title="导入对账账单" @close="modal=''"><form class="modal-form" @submit.prevent="submitImport"><label>资金账户<select v-model="importForm.channelId" required><option v-for="c in channels" :key="c.id" :value="c.id">{{c.name}}</option></select></label><div class="form-grid"><label>数据源<select v-model="importForm.source"><option v-for="s in ['PLATFORM','CLEARING','SETTLEMENT']" :key="s" :value="s">{{label(s)}}</option></select></label><label>账单日期<input v-model="importForm.businessDate" required type="date"/></label></div><label class="upload-zone"><Upload :size="29"/><b>{{chosenFile?.name||'选择一份 CSV 账单'}}</b><span>UTF-8 编码 · 最大 5 MB · 每批最多 10,000 行</span><input type="file" accept=".csv,text/csv" required @change="importFile"/></label><button type="button" class="text-button" @click="downloadFile('/template.csv','导入模板.csv')"><ArrowDownToLine :size="15"/>下载标准 CSV 模板</button><div class="form-note">收款为正数，退款/手续费为负数；金额最多两位小数。文件内日期需与所选日期相同。零交易日可上传仅含表头的账单，重复文件与相同流水会自动跳过。</div><footer class="modal-actions"><button type="button" class="button secondary" @click="modal=''">取消</button><button class="button primary" :disabled="busy||!channels.length">{{busy?'校验并导入中…':'校验并导入'}}</button></footer></form></Modal>
    <Modal v-if="modal==='run'" title="发起对账任务" @close="modal=''"><form class="modal-form" @submit.prevent="runTask"><label>对账项目<select v-model="runForm.projectId" required @change="runProjectChange"><option v-for="p in projects.filter(p=>p.enabled)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><div v-if="selectedProject" class="run-project-info"><span class="type-tag">{{label(selectedProject.kind)}}</span><span>{{label(selectedProject.left_source)}}<ArrowRight :size="13"/>{{label(selectedProject.right_source)}}</span><small>最后对账日：{{selectedProject.last_date||'尚未执行'}}</small></div><label>对账日期<input v-model="runForm.businessDate" required type="date" :max="today"/></label><label v-if="selectedProject?.last_date" class="check-label"><input v-model="runForm.rerun" type="checkbox" @change="runProjectChange"/>重新核对最后一个对账日（保留旧版本）</label><div v-if="selectedProject?.kind==='BALANCE'" class="form-grid"><label>平台侧在途调整（元）<input v-model="runForm.leftAdjustment" required inputmode="decimal"/></label><label>渠道侧在途调整（元）<input v-model="runForm.rightAdjustment" required inputmode="decimal"/></label></div><p class="form-note">对账日期需要连续，双方账单必须就绪。余额按启用日起累计，零交易日也需空账单。重对会冲销旧挂账；已进入差错处理流程的任务不能重对。</p><footer class="modal-actions"><button type="button" class="button secondary" @click="modal=''">取消</button><button class="button primary" :disabled="busy"><Play :size="15"/>{{busy?'执行中…':'执行对账'}}</button></footer></form></Modal>
    <Modal v-if="modal==='run-detail'&&runDetail" :title="`任务 #${runDetail.run.id} · 核对明细`" wide @close="modal=''"><div class="detail-subtitle">{{runDetail.run.project_name}}<span>·</span>{{runDetail.run.business_date}}<span>·</span>版本 {{runDetail.run.attempt}}<span v-if="runDetail.run.stale" class="badge warning">原账单已更新，此结果需重对</span></div><div class="detail-metrics"><div><span>核对标识</span><strong>{{runDetail.run.total_count}}</strong></div><div><span>已对平</span><strong class="green-text">{{runDetail.run.matched_count}}</strong></div><div><span>差异</span><strong class="amber-text">{{runDetail.run.difference_count}}</strong></div><div><span>A / B 总额（元）</span><strong class="detail-amount">{{money(runDetail.run.left_amount)}} / {{money(runDetail.run.right_amount)}}</strong></div></div><div class="table-wrap detail-table"><table><thead><tr><th>核对标识</th><th>核对结果</th><th class="align-right">A 方金额</th><th class="align-right">B 方金额</th><th>明细说明</th></tr></thead><tbody><tr v-for="item in runDetail.items" :key="item.id"><td class="mono">{{item.match_key}}</td><td><span :class="['badge',item.result==='MATCHED'?'success':'warning']">{{label(item.result)}}</span></td><td class="align-right tabular">{{money(item.left_amount)}}</td><td class="align-right tabular">{{money(item.right_amount)}}</td><td class="item-detail">{{item.detail}}</td></tr><tr v-if="!runDetail.items.length"><td colspan="5" class="empty-cell">双方已确认当日空账单，无核对明细。</td></tr></tbody></table></div><footer class="modal-actions"><button class="button secondary" @click="modal=''">关闭</button><button class="button primary" @click="modal='';navigate('differences')">查看差异<ArrowRight :size="14"/></button></footer></Modal>
    <Modal v-if="modal==='difference'&&differenceDetail" :title="`差异 #${selectedDifference.id} · ${label(selectedDifference.status)}`" wide @close="modal=''"><div class="detail-subtitle">{{selectedDifference.project_name}}<span>·</span><b class="mono">{{selectedDifference.match_key}}</b><span class="badge warning">{{label(selectedDifference.result)}}</span></div><div class="detail-metrics"><div><span>A 方金额（元）</span><strong class="detail-amount">{{money(selectedDifference.left_amount)}}</strong></div><div><span>B 方金额（元）</span><strong class="detail-amount">{{money(selectedDifference.right_amount)}}</strong></div><div><span>原始差额（元）</span><strong class="detail-amount amber-text">{{money(selectedDifference.delta)}}</strong></div><div><span>剩余待核销（元）</span><strong class="detail-amount">{{money(remaining)}}</strong></div></div><p class="form-note">{{selectedDifference.detail}}。核销仅登记本地凭证；业务补单、退款等需在业务系统完成，并填写依据。</p><div v-if="differenceDetail.requests.length" class="request-history"><h3>核销申请记录</h3><article v-for="r in differenceDetail.requests" :key="r.id"><div><span :class="['badge',r.status==='APPROVED'?'success':r.status==='PENDING'?'purple':'warning']">{{label(r.status)}}</span><b>{{label(r.method)}} · ¥{{money(r.amount)}}</b><small>{{r.requester}} · {{time(r.created_at)}}</small></div><p>{{r.note}}</p><p class="muted">依据：{{r.evidence}}</p><p v-if="r.reviewer" class="muted">复核：{{r.reviewer}} · {{r.review_note}}</p></article></div><form v-if="!reviewer&&['OPEN','INVESTIGATING'].includes(selectedDifference.status)" class="modal-form" @submit.prevent="perform(()=>api(`/differences/${selectedDifference.id}/resolve`,{method:'POST',body:JSON.stringify(resolutionForm)}),'核销申请已提交，请使用 reviewer 账号复核')"><h3>提交差错核销</h3><div class="form-grid"><label>本次核销金额（元）<input v-model="resolutionForm.amount" required inputmode="decimal"/></label><label>处理类型<select v-model="resolutionForm.method"><option v-for="s in ['MANUAL_CONFIRM','CONFIRM_LOSS','CONFIRM_INCOME','CORRECTED_EXTERNALLY']" :key="s" :value="s">{{label(s)}}</option></select></label></div><label>处理说明<textarea v-model="resolutionForm.note" required minlength="3" maxlength="1000" placeholder="说明差异原因、排查情况与处理结果"></textarea></label><label>处理依据<input v-model="resolutionForm.evidence" required maxlength="1000" placeholder="业务工单号、银行回单号或凭证编号"/></label><footer class="modal-actions"><button v-if="selectedDifference.status==='OPEN'" type="button" class="button secondary" :disabled="busy" @click="perform(()=>api(`/differences/${selectedDifference.id}/investigate`,{method:'POST'}),'已标记为排查中')">标记排查中</button><button class="button primary" :disabled="busy">提交复核<ArrowRight :size="14"/></button></footer></form><form v-else-if="reviewer&&selectedDifference.status==='PENDING_REVIEW'&&pendingRequest" class="modal-form" @submit.prevent="perform(()=>api(`/differences/${selectedDifference.id}/review`,{method:'POST',body:JSON.stringify({approve:true,note:reviewNote})}),'复核已通过，核销凭证已登记')"><label>复核意见<textarea v-model="reviewNote" required maxlength="1000" placeholder="请核实处理依据后填写复核意见"></textarea></label><footer class="modal-actions"><button type="button" class="button secondary danger-text" :disabled="busy||!reviewNote.trim()" @click="perform(()=>api(`/differences/${selectedDifference.id}/review`,{method:'POST',body:JSON.stringify({approve:false,note:reviewNote})}),'已驳回核销申请，退回继续排查')">驳回申请</button><button class="button primary" :disabled="busy"><CheckCheck :size="16"/>通过复核</button></footer></form><div v-else class="modal-actions"><span class="muted">{{selectedDifference.status==='RESOLVED'?'该笔差异已完成核销。':selectedDifference.status==='PENDING_REVIEW'?'等待财务复核员审核，可退出后使用 reviewer 账号登录。':'当前为复核账号，核销申请由操作员提交。'}}</span><button class="button secondary" @click="modal=''">关闭</button></div></Modal>
    <Modal v-if="modal==='help'" title="从第一份账单开始" @close="modal=''"><div class="help-content"><ol><li><b>建立资金账户</b><p>准确填写启用日期和该日首笔交易前的期初余额。</p></li><li><b>归集三类原始账单</b><p>到数据中心下载 CSV 模板，导入平台支付、渠道清算和渠道结算数据。样例文件位于项目的 samples 目录。</p></li><li><b>配置项目并连续执行</b><p>交易按订单与业务类型匹配，资金按费用项核对；余额基于期初余额累计，并支持手动在途调整。</p></li><li><b>处理差异并独立复核</b><p>admin 提交核销并填写凭证依据，reviewer 复核通过后才更新已核销金额。</p></li><li><b>查看凭证与审计</b><p>差异挂账、重对冲销和核销均有记录。原始数据与历史任务版本保留。</p></li></ol><div class="form-note">参考：<a href="https://mp.weixin.qq.com/s/KJZYmE-F-IYIDR0HjArbgw" target="_blank" rel="noopener noreferrer">陈天宇宙《一文搞懂「对账系统」》<ArrowUpRight :size="12"/></a>。本项目独立实现核心流程，银行下载、MQ、业务补单等外部系统尚需接入。</div></div><footer class="modal-actions"><button class="button primary" @click="modal=''">开始使用<ArrowRight :size="15"/></button></footer></Modal>
  </div>
  <div v-if="toast" :class="['toast',{error:toastError}]" role="status"><XCircle v-if="toastError" :size="18"/><CheckCircle2 v-else :size="18"/><span>{{toast}}</span><button aria-label="关闭提示" @click="toast=''"><X :size="15"/></button></div>
</template>
